// 获取AI分析结果
const analysisResult = $input.first().json;

console.log('=== Format Feishu Card 调试信息 ===');
console.log('原始分析结果:', JSON.stringify(analysisResult, null, 2));

// 更安全的数据提取 - 支持多种数据格式
let selectedNews = [];
let todayHotspot = 'AI技术发展';
let industryTrend = 'AI技术持续创新';
let recommendationReason = '精选优质AI资讯';

// 尝试从不同位置获取数据
if (analysisResult.output && analysisResult.output['精选资讯']) {
  selectedNews = analysisResult.output['精选资讯'];
  todayHotspot = analysisResult.output['今日热点'] || todayHotspot;
  industryTrend = analysisResult.output['行业趋势'] || industryTrend;
  recommendationReason = analysisResult.output['推荐理由'] || recommendationReason;
} else if (analysisResult['精选资讯']) {
  selectedNews = analysisResult['精选资讯'];
  todayHotspot = analysisResult['今日热点'] || todayHotspot;
  industryTrend = analysisResult['行业趋势'] || industryTrend;
  recommendationReason = analysisResult['推荐理由'] || recommendationReason;
} else if (Array.isArray(analysisResult)) {
  // 如果整个结果就是数组
  selectedNews = analysisResult;
} else {
  console.log('无法找到精选资讯数据，使用空数组');
  selectedNews = [];
}

console.log(`AI精选了 ${selectedNews.length} 条资讯`);
console.log('今日热点:', todayHotspot);
console.log('行业趋势:', industryTrend);
console.log('推荐理由:', recommendationReason);

// 确保 selectedNews 是数组
if (!Array.isArray(selectedNews)) {
  console.log('selectedNews 不是数组，转换为数组');
  selectedNews = [];
}

// 构建飞书卡片消息
const currentDate = new Date().toLocaleDateString('zh-CN', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  weekday: 'long'
});

// 构建卡片内容
const cardElements = [
  {
    "tag": "div",
    "text": {
      "tag": "lark_md",
      "content": `# 🤖 AI资讯精选 - ${currentDate}\n\n**今日热点**: ${todayHotspot}\n\n**行业趋势**: ${industryTrend}\n\n**推荐理由**: ${recommendationReason}\n\n---`
    }
  }
];

// 为每条精选资讯添加卡片元素
selectedNews.forEach((news, index) => {
  const importanceEmoji = news.重要性 === '高' ? '🔥' : news.重要性 === '中' ? '⭐' : '📰';
  const keywordsText = Array.isArray(news.关键词) ? news.关键词.join('、') : news.关键词 || '';
  const categoryText = Array.isArray(news.分类) ? news.分类.join('、') : news.分类 || '';

  cardElements.push({
    "tag": "div",
    "text": {
      "tag": "lark_md",
      "content": `## ${importanceEmoji} ${news.标题}\n\n**来源**: ${news.来源} | **评分**: ${news.评分}/100\n\n**摘要**: ${news.摘要}\n\n**关键词**: ${keywordsText}\n\n**分类**: ${categoryText}\n\n[查看原文](${news.链接})\n\n---`
    }
  });
});

// 添加统计信息
cardElements.push({
  "tag": "div",
  "text": {
    "tag": "lark_md",
    "content": `\n📊 **统计信息**\n- 精选资讯: ${selectedNews.length} 条\n- 生成时间: ${new Date().toLocaleString('zh-CN')}\n- 数据来源: 飞书多维表格`
  }
});

// 构建完整的卡片消息
const cardMessage = {
  "msg_type": "interactive",
  "card": {
    "config": {
      "wide_screen_mode": true
    },
    "elements": cardElements,
    "header": {
      "title": {
        "tag": "plain_text",
        "content": "🤖 AI资讯精选"
      },
      "template": "blue"
    }
  }
};

console.log('构建的卡片消息:', JSON.stringify(cardMessage, null, 2));

return [{
  json: {
    message: cardMessage,
    webhook_url: $('Configuration').first().json.FEISHU_WEBHOOK_URL,
    selected_count: selectedNews.length,
    today_hotspot: todayHotspot,
    industry_trend: industryTrend
  }
}];

