const analysisResult = $input.first().json;

console.log('=== Format to Weibo 调试信息 ===');
console.log('原始分析结果:', JSON.stringify(analysisResult, null, 2));

// 更安全的数据提取 - 支持多种数据格式
let selectedNews = [];
let todayHotspot = 'AI技术发展';
let industryTrend = 'AI技术持续创新';
let recommendationReason = '精选优质AI资讯';

// 尝试从不同位置获取数据
if (analysisResult.output && analysisResult.output['精选资讯']) {
  selectedNews = analysisResult.output['精选资讯'];
  todayHotspot = analysisResult.output['今日热点'] || todayHotspot;
  industryTrend = analysisResult.output['行业趋势'] || industryTrend;
  recommendationReason = analysisResult.output['推荐理由'] || recommendationReason;
} else if (analysisResult['精选资讯']) {
  selectedNews = analysisResult['精选资讯'];
  todayHotspot = analysisResult['今日热点'] || todayHotspot;
  industryTrend = analysisResult.output['行业趋势'] || industryTrend;
  recommendationReason = analysisResult['推荐理由'] || recommendationReason;
} else if (Array.isArray(analysisResult)) {
  // 如果整个结果就是数组
  selectedNews = analysisResult;
} else {
  console.log('无法找到精选资讯数据，使用空数组');
  selectedNews = [];
}

console.log(`AI精选了 ${selectedNews.length} 条资讯`);
console.log('今日热点:', todayHotspot);
console.log('行业趋势:', industryTrend);
console.log('推荐理由:', recommendationReason);

// 确保 selectedNews 是数组
if (!Array.isArray(selectedNews)) {
  console.log('selectedNews 不是数组，转换为数组');
  selectedNews = [];
}

// 构建微博内容
const currentDate = new Date().toLocaleDateString('zh-CN', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  weekday: 'long'
});

// 微博内容生成（1000字限制）
let weiboContent = ` 🤖AI资讯精选 - ${currentDate}\n\n🔥 今日热点\n${todayHotspot}\n\n📈 行业趋势\n${industryTrend}\n\n🤖 精选资讯\n\n`;

// 为每条精选资讯添加内容
selectedNews.forEach((news, index) => {
  const importanceEmoji = news.重要性 === '高' ? '🔥' : news.重要性 === '中' ? '⭐' : '📰';
  const keywordsText = Array.isArray(news.关键词) ? news.关键词.join('、') : news.关键词 || '';
  const categoryText = Array.isArray(news.分类) ? news.分类.join('、') : news.分类 || '';

  weiboContent += `${index + 1}. ${importanceEmoji} ${news.标题}\n来源: ${news.来源} | 评分: ${news.评分}/100\n${news.摘要}\n关键词: ${keywordsText}\n分类: ${categoryText}\n链接: ${news.链接}\n\n`;
});

// 添加推荐理由和标签
weiboContent += `🤖 推荐理由\n${recommendationReason}\n\n#AI资讯 #人工智能 #科技前沿 #AI技术`;

// 检查字数限制（1000字）
if (weiboContent.length > 1000) {
  console.log(`微博内容长度: ${weiboContent.length} 字，超过1000字限制，进行截断`);

  // 截断到1000字，保留完整结构
  weiboContent = weiboContent.substring(0, 997) + '...';
}

console.log(`微博内容长度: ${weiboContent.length} 字`);
console.log('微博内容预览:', weiboContent.substring(0, 200) + '...');

// 返回微博发布所需的数据
return [{
  json: {
    weibo_content: weiboContent,
    weibo_access_token: $('Configuration').first().json.WEIBO_ACCESS_TOKEN,
    weibo_uid: $('Configuration').first().json.WEIBO_UID,
    content_length: weiboContent.length,
    selected_count: selectedNews.length,
    today_hotspot: todayHotspot,
    industry_trend: industryTrend
  }
}];

// 新节点：Prepare Data for AI Analysis
const articles = $input.all();

console.log('=== 准备AI分析数据 ===');
console.log('文章数量:', articles.length);

// 构建AI分析所需的文本格式
const articlesText = articles.map((article, index) => {
  const data = article.json;
  return `${index + 1}. 标题：${data.title}
   来源：${data.source}
   评分：${data.relevance_score}
   摘要：${data.summary}
   关键词：${data.keywords}
   分类：${data.category}
   链接：${data.url}`;
}).join('\n\n');

console.log('构建的文章文本长度:', articlesText.length);
console.log('文章文本预览:', articlesText.substring(0, 500) + '...');

// 返回汇总后的数据
return [{
  json: {
    articles_text: articlesText,  // 所有文章的汇总文本
    articles_count: articles.length,  // 文章数量
    articles_data: articles.map(a => a.json)  // 原始文章数据数组
  }
}];
